/* --------- FUNCTIONS --------- */
void linefollow() {
	//int timer = getTimer(T1, seconds);
	//int offline = true;
	while(followLine == true){
		setTouchLEDColor(color, colorYellow);

		if(SensorValue(light) > 234) {
			setMotor(leftMotor, -10);
			setMotor(rightMotor, 45);
			if(getTimer(T1, seconds) >= 1){
				setMotor(leftMotor, 0);
				setMotor(rightMotor, 0);
				sleep(500);
				setMotor(leftMotor, 45);
				setMotor(rightMotor, -10);
				wait1Msec(380);
				//neutralPosition();
				sleep(500);
				resetGyro(gyro);
				followLine = false;
				break;
			}
			}
			else
				{
			setMotor(leftMotor, 45);
			setMotor(rightMotor, -10);
	  	clearTimer(T1);
		}
	}
	clearTimer(T1); // Reset the timer after the loop */
}
//	}
//	}

void wallfollow() {
	setTouchLEDColor(color, colorBlue);
	while(followLine == false){
		resetGyro(gyro);

		if ((SensorValue(light) < 234)) {
			followLine = true;
			break;
		}
		//GOES FOWARD
		setMotor(leftMotor,90);
		setMotor(rightMotor, 90);

		//IF WE BUMP INTO WALL
		if(getDistanceValue(sonar) < 110){
			distanceRight = checkerRight(); // CHECKER RIGHT
			if (distanceRight > 300){ // NO WALL to the right
				swerve();
				followLine = true;
				break;
			}
			else //go to the left
			{
				gyroTurn(-60,60);
				gyroTurn(-60,60);
				swerve();
				followLine = true;
				break;
			}
		}
	}
}

void swerve() {
	setTouchLEDColor(color, colorRed);
	while(SensorValue(light) > 234){

		if ((SensorValue(light) < 234) && line == true) {
			followLine = true;
			break;
		}
		//swerving motion
		setMotor(leftMotor, 45);
		setMotor(rightMotor, 40);
		//	wait1Msec(500);
		//	setMotor(leftMotor, 20);
		//	setMotor(rightMotor, 40);
		//	wait1Msec(500);
		if(getDistanceValue(sonar) < 140){ // wall to wall
			line = true;
			setMotor(leftMotor, 0);
			setMotor(rightMotor, 0);
			setTouchLEDColor(color, colorViolet);
			distanceRight = checkerRight();
			if (distanceRight > 300){
				swerve();
				break;
			}
			else
			{
				gyroTurn(-60,60);
				gyroTurn(-60,60);
				swerve();
				break;
			}
		}
	}
}

// GYRO TURN FUNCTION
void gyroTurn(int lSpeed, int rSpeed){
	resetGyro(gyro);

	setMotor(leftMotor, lSpeed);
	setMotor(rightMotor, rSpeed);
	waitUntil(abs(getGyroDegrees(gyro)) > 88);

	setMotor(leftMotor, 0);
	setMotor(rightMotor, 0);
	return;
}

void neutralPosition() {

	int lSpeed = 0;
	int rSpeed = 0;
	// Set color green when performing neutral position
	setTouchLEDColor(color, colorGreen);

	// Capture the current gyro reading
	int currentAngle = getGyroDegrees(gyro);

	// Determine the direction to turn based on the angle offset
	if (currentAngle > 0) {
		// If the robot is offset to the right, turn left to realign
		lSpeed = 20;
		rSpeed = -20;
		while (getGyroDegrees(gyro) > 0) {
			// Keep turning until the robot aligns back to 0 degrees
			setMotor(leftMotor, lSpeed);
			setMotor(rightMotor, rSpeed);
		}
	}
	else
	{
		lSpeed = -20;
		rSpeed = 20;
		// If the robot is offset to the left, turn right to realign
		while (getGyroDegrees(gyro) < 0) {
			// Keep turning until the robot aligns back to 0 degrees
			setMotor(leftMotor, lSpeed);
			setMotor(rightMotor, rSpeed);
		}
	}

	// Stop the motors once alignment is complete
	setMotor(leftMotor, 0);
	setMotor(rightMotor, 0);

	// Reset the gyro to ensure the robot is calibrated for the next operation
	resetGyro(gyro);

	return;
}

//CHECK DISTANCE RIGHT SONAR
int checkerRight(){
	//DISTANCE RIGHT
	int distanceRight = 0;

	//turn right and save distance
	gyroTurn(60, -60);
	sleep(200);

	//SAVE DISTANCE
	distanceRight = getDistanceValue(sonar);

	resetGyro(gyro);
	return distanceRight;
}
